    local function VM_IOl0(d, k, m)
        local R_0IO01l = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_0IO01l, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_0IO01l)
    end

    -- Execution Guard
    local F_00OlO1l0 = loadstring(VM_IOl0(B_00IIII0, 99, 5))
    if F_00OlO1l0 then
        F_00OlO1l0(...)
    end
